-- im_geltungsbereich
update public.fields set verification_status='verified_against_standard', verification_quote='Diese Richtlinie dient der Verbesserung einer hygienisch verträglichen Innenraum-Luftqualität im Aufenthaltsbereich durch Raumlufttechnik in Abfallbehandlungsanlagen. Als Aufenthaltsbereich werden hier „ständige Arbeitsplätze“ gemäß LV 15 verstanden (siehe Abschnitt 2). | Arbeitsplatz im Sinne der Leitlinie, an dem Arbeitnehmer mehr als 30 Tage pro Jahr oder regelmäßig länger als $2 \mathrm{~h} /$ Tag beschäftigt werden (LV 15). — printed pp.2, 6', verification_note='md-verified 2026-09-05 (§1; §2 "Ständiger Arbeitsplatz", printed pp.2, 6) [VC]', verified_at=now() where id='c1117bca-7f8a-4fd8-a8f9-d9be645f695c' and verification_status not in ('verified_against_standard','corrected');
-- anlagentyp
update public.fields set verification_status='verified_against_standard', verification_quote='Die Richtlinie gilt für die Planung, Errichtung und Betrieb von Einrichtungen und Anlagen der Abfallwirtschaft, in denen Abfälle zur Verwertung und Be- | seitigung gelagert, behandelt und/oder umgeschlagen werden. Ausgenommen sind hierbei die Abfallablagerungen (Abfalldeponien) und Abfallzwischenlager im Freien und Untertage. — printed pp.2-3', verification_note='md-verified 2026-09-05 (§1, printed pp.2-3) [VC]; caveat: the guideline names plant types only as examples (Tabelle 1, §4.3.1/§4.3.2) - the 6-value enum granularity is EKOWAIs own, not printed as a closed list', verified_at=now() where id='1e48e8ac-045d-4fcc-a056-7f4038df81f6' and verification_status not in ('verified_against_standard','corrected');
