-- gefahrstoffart
update public.fields set verification_status='verified_against_standard', verification_quote='In Abhängigkeit von den genannten Parametern können Aerosole, Gase und/oder Stäube auftreten. Dabei kann es sich z.B. um aus Lösungsmitteln stammende Aromaten oder aus Reinigungsmitteln stammende Tenside handeln. Im Bereich der Stäube kommen organische, silikogene, schwermetallhaltige aber potenziell auch asbesthaltige Belastungen in Betracht. Je nach Art der Gefahrstoffe ist dabei annähernd das gesamte Spektrum an gesundheitlichen Beeinträchtigungen, wie toxische, krebserzeugende oder sensibilisierende Effekte, möglich. — printed p.8', verification_note='md-verified 2026-09-05 (§3.2, printed p.8) [VC]', verified_at=now() where id='8d9d0bdb-552d-4a57-8e48-a01a06f04577' and verification_status not in ('verified_against_standard','corrected');
