-- arbeitsmed_vorsorge_angeboten
update public.fields set verification_status='verified_against_standard', verification_quote='Die arbeitsmedizinische Vorsorge nach § 15 BiostoffV beinhaltet die Untersuchung, Beratung und Impfung der Beschäftigten. Den Beschäftigten muss bei Tätigkeiten in Schutzstufe 3 eine arbeitsmedizinische Untersuchung angeboten werden. Gleiches gilt bei Schutzstufe 2, es sei denn, dass auf Grund der Gefährdungsbeurteilung und der getroffenen Schutzmaßnahmen nicht mit einem Gesundheitsschaden zu rechnen ist. — printed p.9', verification_note='md-verified 2026-09-05 (§3.3.1, printed p.9) [VC]', verified_at=now() where id='621f4903-f811-4b83-8af9-c97d608ab4e3' and verification_status not in ('verified_against_standard','corrected');
