-- c_schimmelpilze_luft
update public.fields set verification_status='verified_against_standard', verification_quote='Als Indikator für mikrobielle Belastungen in der Arbeitsplatzatmosphäre in Abfallbehandlungsanlagen dient der Gehalt an Sporen mesophiler Schimmelpilze. Zur Kontrolle der Funktion und Wirksamkeit von technischen Schutzmaßnahmen, insbesondere von Lüftungsanlagen, dient der Technische Kontrollwert. Er wurde zunächst für Sortierkabinen, Fahrerkabinen und Steuerstände in biologischen Abfallbehandlungsanlagen eingeführt (TRBA 211). Er beträgt $5 \cdot 10^{4} \mathrm{KBE} / \mathrm{m}^{3}$ Luft. — printed p.44', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.44) [VC]', verified_at=now() where id='927fa886-fdf4-44f1-a308-ccdb2ae85326' and verification_status not in ('verified_against_standard','corrected');
