-- raumluftgeschwindigkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Der aus Behaglichkeitsgründen zulässige Bereich der Raumluftgeschwindigkeiten ist für Fertigungsstätten in VDI 3802, Bild 2 dargestellt. Mit steigender Raumlufttemperatur, steigender Aktivität und schwerer Bekleidung erhöht sich die zulässige Raumluftgeschwindigkeit. Die angegebene Raumluftgeschwindigkeit ist der zeitliche Mittelwert. — printed p.45', verification_note='md-verified 2026-09-05 (§6.3, printed p.45) [VC]; NR caveat: the permissible range itself is printed in VDI 3802 Bild 2, not in VDI 2163', verified_at=now() where id='e81521f1-49d1-4924-9a82-56638a9e20ff' and verification_status not in ('verified_against_standard','corrected');
