update public.fields set verification_status='verified_against_standard', verification_quote='Nach der Arbeitsstättenrichtlinie ASR5 soll der Außenluftstrom $40 \mathrm{~m}^{3} / \mathrm{h}$ bis $60 \mathrm{~m}^{3} / \mathrm{h}$ je Person - bei überwiegend nicht sitzender Tätigkeit - betragen und bei körperlich schwerer Arbeit $65 \mathrm{~m}^{3} / \mathrm{h}$ je Person. Bei intensiver Geruchsverschlechterung sind zusätzlich $20 \mathrm{~m}^{3} / \mathrm{h}$ je Person vorzusehen. Der aus diesen Angaben resultierende Luftstrom muss bei der Auslegung der lüftungstechnischen Anlage als absolutes Minimum angesehen werden. — printed p.25', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.25) [VC]; value applies only "bei körperlich schwerer Arbeit"', verified_at=now() where id='d4eb2584-54f4-4fe8-a5da-2569306d1a9e' and verification_status not in ('verified_against_standard','corrected');
