-- kritischer_befund
update public.fields set verification_status='verified_against_standard', verification_quote='Ein kritischer Befund liegt beispielsweise vor bei: | - Überschreitung von Technischen Kontrollwerten (TKW) (siehe TRBA 405) | - sichtbarem Schimmelpilzbefall oder anderen mikrobiellen Belägen | Im Falle eines kritischen Befundes muss ein Hygieniker (oder ein anderer Spezialist mit vergleichbarer Ausbildung) sowie gegebenenfalls weiteres Fachpersonal hinzugezogen und der Betriebsarzt beteiligt werden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.4, printed p.29) [VC]', verified_at=now() where id='c21dac21-0776-4fde-9a53-2c7d5a572f1a' and verification_status not in ('verified_against_standard','corrected');
