-- filterstufen_anzahl
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist zu empfehlen zwei Filterstufen einzusetzen. Die Außenluft soll möglichst mit einer Filterstufe F7, mindestens F5 und die Zuluft mit einer zweiten Filterstufe, möglichst F9, mindestens mit F7 gefiltert werden. Bei einstufiger Filterung ist mindestens die Filterstufe F7 einzusetzen. — printed p.27', verification_note='md-verified 2026-09-05 (§4.4.3, printed p.27) [VC]; "zu empfehlen" - a recommendation, not a "muss"', verified_at=now() where id='05ae69c5-40a7-4d71-9c36-443bf914d253' and verification_status not in ('verified_against_standard','corrected');
