update public.fields set verification_status='verified_against_standard', verification_quote='(2) Diese Forderung ist erfüllt, wenn für die Beschäftigten z.B. folgende persönliche Schutzausrüstungen zur Verfügung gestellt werden: | - körperbedeckende Kleidung, bestehend aus Kopfbedeckung, Arbeitsanzug oder Berufsmantel gemäß EN 340 — printed p.30', verification_note='md-verified 2026-09-05 (§4.5, printed p.30) [VC]; the source list is introduced by "z.B." - exemplary means of fulfilling the requirement', verified_at=now() where id='cb7afcad-5bac-4d6f-bad0-229c8297003e' and verification_status not in ('verified_against_standard','corrected');
