-- tkw_schimmelpilzsporen
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Kontrolle der Funktion und Wirksamkeit von technischen Schutzmaßnahmen, insbesondere von Lüftungsanlagen, dient der Technische Kontrollwert. Er wurde zunächst für Sortierkabinen, Fahrerkabinen und Steuerstände in biologischen Abfallbehandlungsanlagen eingeführt (TRBA 211). Er beträgt $5 \cdot 10^{4} \mathrm{KBE} / \mathrm{m}^{3}$ Luft. | Wird der Wert von $5 \cdot 10^{4} \mathrm{KBE} / \mathrm{m}^{3}$ Luft um mehr als das Doppelte überschritten, sind die technischen Schutzmaßnahmen des Betriebes, insbesondere die Lüftungstechnik, zu überprüfen und dem Stand der Technik anzupassen. — printed p.44', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.44) [VC]', verified_at=now() where id='8612da15-4787-4905-97a8-0bade8ee878e' and verification_status not in ('verified_against_standard','corrected');
-- c_endotoxine_kontrollwert
