-- gesamtkeimzahl_wasser
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Verwendung von Wasser soll die Gesamtkeimzahl den Wert von $1000 \mathrm{KBE} / \mathrm{m} \ell$ bei $20^{\circ} \mathrm{C}$ und $36^{\circ} \mathrm{C}$ nicht überschreiten. Die Überprüfung erfolgt in halbmonatlichen Abständen. — printed p.44', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.44) [VC]', verified_at=now() where id='344b0243-4098-4ce3-94f6-7c20dffc4cf2' and verification_status not in ('verified_against_standard','corrected');
-- legionellen_wasser
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Legionellen darf die Keimzahl den Wert von $1 \mathrm{KBE} / \mathrm{m}$ t nicht überschreiten. Die Untersuchung hierzu ist mit der Hygiene-Inspektion alle zwei Jahre durchzuführen. — printed p.44', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.44) [VC]; transcript OCR defect: the unit reads "$1 \mathrm{KBE} / \mathrm{m}$ t" where the print has KBE/ml', verified_at=now() where id='c62de1c5-0a72-4afa-863e-0a5efd4cb723' and verification_status not in ('verified_against_standard','corrected');
-- gesamtkoloniezahl_umlaufwasser
update public.fields set verification_status='verified_against_standard', verification_quote='Die zulässige Gesamtkoloniezahl soll den Richtwert von $10000 \mathrm{KBE} / \mathrm{m} \ell$ nicht überschreiten. Bei Überschreitung dieser Werte muss eine Entkeimung durchgeführt werden | 9.4 & Schätzung der Gesamtkoloniezahl des Umlaufwassers mit Dip-Slides (nur bei Betrieb) & bei $>10000 \mathrm{KBE} / \mathrm{m} \ell$ entleeren, Reinigung und Desinfektion, ggf. über kontinuierliche Entkeimung entscheiden — printed pp.35, 39', verification_note='md-verified 2026-09-05 (§5.2.9; Tabelle 4 Pos.9.4, printed pp.35, 39) [VC]', verified_at=now() where id='42efd6aa-7763-44e8-b357-5f0e8590952b' and verification_status not in ('verified_against_standard','corrected');
-- koloniezahl_befeuchterwasser_dipslide
update public.fields set verification_status='verified_against_standard', verification_quote='5.1.3 & Koloniezahlschätzung des Befeuchterwassers (Dip-Slides) & bei Koloniezahl $>1000 \mathrm{KBE} / \mathrm{m} \ell$ : reinigen mit Reinigungsmittel, ausspülen und austrocknen der Wanne, ggf. Desinfektion & halbmonatlich — printed p.37', verification_note='md-verified 2026-09-05 (Tabelle 4 Pos.5.1.3 (§5.2.5), printed p.37) [VC]', verified_at=now() where id='39e07874-c343-4506-8c12-7e7607d3f6d3' and verification_status not in ('verified_against_standard','corrected');
-- zuluft_keimgehalt_verhaeltnis
update public.fields set verification_status='verified_against_standard', verification_quote='Der Gehalt der Zuluft an Mikroorganismen und biologischen Inhaltsstoffen darf den der Außenluft am Referenzort im zeitlichen Mittel in keiner Kategorie überschreiten. Dies gilt insbesondere auch für das Keimspektrum. Da die Außenluft auf dem Betriebsgelände von Abfallbehandlungsanlagen durch Lagerung, Umschlag und Vorbehandlung der angelieferten Materialien erheblich mit Mikroorganismen belastet sein kann, sind die Referenzmessungen an einem repräsentativen nicht kontaminierten Ort, beispielsweise 100 m vom Betriebsgelände entfernt, in Lee der Anlage durchzuführen. — printed p.44', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.44) [VC]', verified_at=now() where id='b804b3a0-640f-41c1-826e-fb9f3626ae92' and verification_status not in ('verified_against_standard','corrected');
-- filter_druckdifferenz
update public.fields set verification_status='verified_against_standard', verification_quote='ist in regelmäßigen Abständen eine Überprüfung vorzunehmen, bei der die folgenden Parameter zu erfassen und für jede Filterstufe getrennt zu dokumentieren sind: | - Druckdifferenz | Ist die zulässige Enddruckdifferenz des Luftfilters erreicht oder weisen die Luftfilter technische und/oder hygienische Funktionsmängel auf, so sind sie auszuwechseln. — printed p.33', verification_note='md-verified 2026-09-05 (§5.2.7, printed p.33) [VC]', verified_at=now() where id='1d8f7ccc-902c-4cd5-aa82-ade786ec1cee' and verification_status not in ('verified_against_standard','corrected');
