-- kammerzentrale_wasser_intervall
update public.fields set verification_status='verified_against_standard', verification_quote='Kammerzentralen und Gerätegehäuse müssen vor der ersten Inbetriebnahme einer gründlichen Innenreinigung unterzogen werden. Im weiteren Betrieb ist eine halbjährliche Prüfung auf Verschmutzung, Beschädigung und Korrosion sowie auf Wasserbildung (alle drei Monate) notwendig. Bei Bedarf ist eine Reinigung vorzunehmen bzw. die Ursache für die Hygienemängel zu ermitteln und zu beseitigen. — printed p.32', verification_note='md-verified 2026-09-05 (§5.2.4, printed p.32) [VC]; CONFLICT: the §5.2.4 prose says "alle drei Monate" while Tabelle 4 Pos.4.2 marks the 6-month column - staged for a ruling', verified_at=now() where id='d540de2a-abd7-48ae-9ca8-0516ee65e867' and verification_status not in ('verified_against_standard','corrected');
-- aussenluftdurchlass_pruefintervall
