-- naehrboden_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Geräteoberflächen in hygienischen Problemzonen von Lüftungsanlagen (Wärmetauscher, Kühler, Filter etc.) sollen mittels Abklatschnährböden (z. B. so genannte Rodac-Platten) beprobt werden. Als Nährböden werden verwendet: Bakterien: CASO-Agar; Schimmelpilze: DG-18-Agar; Actinomyceten: Glycerin-ArgininAgar. — printed p.43', verification_note='md-verified 2026-09-05 (§6.2.3, printed p.43) [VC]; transcript renders "Glycerin-ArgininAgar" (print: Glycerin-Arginin-Agar)', verified_at=now() where id='65d665ff-3a0f-4f59-8c90-443dbe214994' and verification_status not in ('verified_against_standard','corrected');
